def desired_workers(queue_depth: int, per_worker: int = 10,
                    min_w: int = 2, max_w: int = 100) -> int:
    # scale on backlog: enough workers to drain the queue, within bounds
    needed = -(-queue_depth // per_worker)   # ceil division
    return max(min_w, min(max_w, needed))

for depth in (0, 45, 500, 5000):
    print(f"queue={depth:>4} -> workers={desired_workers(depth)}")
# scales up with backlog, capped so it never runs away

class RunBudget:
    def __init__(self, max_steps=15, max_tokens=50_000, deadline_s=120):
        self.max_steps, self.max_tokens, self.deadline_s = max_steps, max_tokens, deadline_s
        self.steps, self.tokens, self.start = 0, 0, time.time()
    def check(self) -> None:
        self.steps += 1
        if self.steps > self.max_steps:
            raise BudgetExceeded("step cap")
        if self.tokens > self.max_tokens:
            raise BudgetExceeded("token cap")
        if time.time() - self.start > self.deadline_s:
            raise BudgetExceeded("deadline")

# call budget.check() at the top of every agent-loop iteration
